141: // Classification returns a simplified actor and action classification for the step.
142: func (s *Step) Classification() (actor string, action string) {
143: 	if s.Source == "USER_EXPLICIT" {
144: 		actor = "user"
145: 	} else if s.Source == "MODEL" {
146: 		actor = "model"
147: 	} else {
148: 		actor = "system"
149: 	}
150: 	
151: 	action = s.Type
152: 	return actor, action
153: }
