98: // the slice of files representing the primary transcript source.
99: // Prioritizes transcript_full.jsonl, then chunks, then transcript.jsonl.
100: func ResolvePrimaryTranscript(srcDirOrFile string) ([]string, error) {
101: 	fi, err := os.Stat(srcDirOrFile)
102: 	if err != nil {
103: 		return nil, fmt.Errorf("stat transcript path %s: %w", srcDirOrFile, err)
104: 	}
105: 
106: 	if !fi.IsDir() {
107: 		// If a compact transcript.jsonl was passed, check if transcript_full.jsonl exists in the same dir
108: 		dir := filepath.Dir(srcDirOrFile)
109: 		base := filepath.Base(srcDirOrFile)
110: 		if base == "transcript.jsonl" {
111: 			fullPath := filepath.Join(dir, "transcript_full.jsonl")
112: 			if _, err := os.Stat(fullPath); err == nil {
113: 				return []string{fullPath}, nil
114: 			}
115: 		}
116: 		return []string{srcDirOrFile}, nil
117: 	}
118: 
119: 	// If directory has .system_generated/logs subpath (standard Antigravity brain layout)
120: 	sysLogs := filepath.Join(srcDirOrFile, ".system_generated", "logs")
121: 	if sysStat, err := os.Stat(sysLogs); err == nil && sysStat.IsDir() {
122: 		return ResolvePrimaryTranscript(sysLogs)
123: 	}
124: 
125: 	// 1. Monolithic transcript_full.jsonl
126: 	fullPath := filepath.Join(srcDirOrFile, "transcript_full.jsonl")
127: 	if _, err := os.Stat(fullPath); err == nil {
128: 		return []string{fullPath}, nil
129: 	}
130: 
131: 	// 2. Chunks under chunks/transcript_full/
132: 	chunksDir := filepath.Join(srcDirOrFile, "chunks", "transcript_full")
133: 	if entries, err := os.ReadDir(chunksDir); err == nil {
134: 		var chunks []string
135: 		for _, entry := range entries {
136: 			if !entry.IsDir() && filepath.Ext(entry.Name()) == ".jsonl" {
137: 				chunks = append(chunks, filepath.Join(chunksDir, entry.Name()))
138: 			}
139: 		}
140: 		if len(chunks) > 0 {
141: 			sort.Strings(chunks)
142: 			return chunks, nil
143: 		}
144: 	}
145: 
146: 	// 3. Compact transcript.jsonl fallback
147: 	compactPath := filepath.Join(srcDirOrFile, "transcript.jsonl")
148: 	if _, err := os.Stat(compactPath); err == nil {
149: 		return []string{compactPath}, nil
150: 	}
151: 
152: 	return nil, fmt.Errorf("no transcript source found in %s", srcDirOrFile)
153: }
