224: 		}
225: 
226: 		n, err := io.CopyN(hasher, reader, existingState.ByteOffset)
227: 		if err != nil || n != existingState.ByteOffset {
228: 			needsFullCopy = true
229: 			closeAll(closers)
230: 		} else {
231: 			prefixMD5 := hex.EncodeToString(hasher.Sum(nil))
232: 			if prefixMD5 != existingState.PrefixHash {
233: 				// Prefix hash mismatch: session was reset, branched, or rewritten.
