362: func openReaders(files []string) ([]io.ReadCloser, io.Reader, error) {
363: 	closers := make([]io.ReadCloser, len(files))
364: 	readers := make([]io.Reader, len(files))
365: 	for i, file := range files {
366: 		f, err := os.Open(file)
367: 		if err != nil {
368: 			for j := 0; j < i; j++ {
369: 				_ = closers[j].Close()
370: 			}
371: 			return nil, nil, err
372: 		}
373: 		closers[i] = f
374: 		readers[i] = f
375: 	}
376: 	return closers, io.MultiReader(readers...), nil
377: }
