27: 	// Match scp style: [user@]host:path
28: 	if !strings.Contains(raw, "://") && strings.Contains(raw, ":") {
29: 		parts := strings.SplitN(raw, ":", 2)
30: 		hostPart := parts[0]
31: 		pathPart := parts[1]
