package gitops

import (
	"context"
	"os/exec"
	"strings"
	"time"
)

// GetCurrentBranch returns the active branch name for the repository at repoRoot.
// Returns an empty string if in detached HEAD state or unable to determine branch.
func GetCurrentBranch(repoRoot string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	return GetCurrentBranchWithContext(ctx, repoRoot)
}

// GetCurrentBranchWithContext returns the active branch name using the provided context.
func GetCurrentBranchWithContext(ctx context.Context, repoRoot string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "branch", "--show-current")
	out, err := cmd.Output()
	if err == nil {
		b := strings.TrimSpace(string(out))
		if b != "" {
			return b, nil
		}
	}

	// Fallback: rev-parse --abbrev-ref HEAD
	cmd = exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
	out, err = cmd.Output()
	if err == nil {
		ref := strings.TrimSpace(string(out))
		if ref != "HEAD" && ref != "" {
			return ref, nil
		}
	}

	return "", nil
}

// GetHeadCommit returns the current HEAD commit hash for the repository at repoRoot.
func GetHeadCommit(repoRoot string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	return GetHeadCommitWithContext(ctx, repoRoot)
}

// GetHeadCommitWithContext returns the HEAD commit hash using the provided context.
func GetHeadCommitWithContext(ctx context.Context, repoRoot string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "HEAD")
	out, err := cmd.Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

package gitops

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func runGitCmd(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %s failed: %v (output: %s)", strings.Join(args, " "), err, string(out))
	}
	return strings.TrimSpace(string(out))
}

func TestGitBranchAndHead(t *testing.T) {
	tempDir := t.TempDir()
	runGitCmd(t, tempDir, "init", "-b", "feature-test")
	runGitCmd(t, tempDir, "config", "user.name", "Test User")
	runGitCmd(t, tempDir, "config", "user.email", "test@example.com")

	// In an empty repo without commits
	branch, err := GetCurrentBranch(tempDir)
	if err != nil {
		t.Fatalf("GetCurrentBranch failed on empty repo: %v", err)
	}
	if branch != "feature-test" {
		t.Errorf("expected branch feature-test, got %q", branch)
	}

	head, err := GetHeadCommit(tempDir)
	if err == nil && head != "" {
		t.Errorf("expected empty/error head on empty repo, got %q", head)
	}

	// Create a commit
	testFile := filepath.Join(tempDir, "test.txt")
	if err := os.WriteFile(testFile, []byte("hello\n"), 0644); err != nil {
		t.Fatalf("failed to write test file: %v", err)
	}
	runGitCmd(t, tempDir, "add", "test.txt")
	runGitCmd(t, tempDir, "commit", "-m", "initial commit")

	branch, err = GetCurrentBranch(tempDir)
	if err != nil {
		t.Fatalf("GetCurrentBranch failed: %v", err)
	}
	if branch != "feature-test" {
		t.Errorf("expected branch feature-test, got %q", branch)
	}

	head, err = GetHeadCommit(tempDir)
	if err != nil {
		t.Fatalf("GetHeadCommit failed: %v", err)
	}
	if len(head) != 40 {
		t.Errorf("expected 40-char SHA head commit, got %q", head)
	}

	// Test detached HEAD
	runGitCmd(t, tempDir, "checkout", head)
	detachedBranch, err := GetCurrentBranch(tempDir)
	if err != nil {
		t.Fatalf("GetCurrentBranch on detached head failed: %v", err)
	}
	if detachedBranch != "" {
		t.Errorf("expected empty branch on detached HEAD, got %q", detachedBranch)
	}

	detachedHead, err := GetHeadCommit(tempDir)
	if err != nil {
		t.Fatalf("GetHeadCommit on detached head failed: %v", err)
	}
	if detachedHead != head {
		t.Errorf("expected head %q, got %q", head, detachedHead)
	}
}

